const STALE_CLOSE_SQL = `with c as (
  update jarvis.items set status = 'done'
  where type = 'reminder' and status = 'open' and parent_id is null and recurrence is null and last_notified_at is not null
    and remind_at < (((now() at time zone 'Asia/Kolkata')::date)::timestamp at time zone 'Asia/Kolkata')
    and not (cardinality($1::text[]) > 0 and not exists (select 1 from unnest($1::text[]) s where lower(title) not like '%' || s || '%'))
  returning title
)
select (select count(*) from c)::int as closed, (select coalesce(json_agg(title), '[]'::json) from c) as titles`;

const ctx = $('Prepare').first().json;
